import React, { useEffect, useState } from 'react';
import { getMyTestDrives } from '../services/testDriveService';
import { useAuth } from '../context/AuthContext';
import { motion } from 'framer-motion';

const UserDashboard = () => {
  const { user } = useAuth();
  const [testDrives, setTestDrives] = useState([]);

  useEffect(() => {
    getMyTestDrives().then(res => setTestDrives(res.data)).catch(console.error);
  }, []);

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ padding: '2rem' }}>
      <h2>Личный кабинет – {user.full_name}</h2>
      <h3>Мои заявки на тест-драйв</h3>
      {testDrives.length === 0 ? <p>Нет заявок</p> : (
        <ul>
          {testDrives.map(td => (
            <li key={td.id}>Авто ID {td.car_id} – {td.preferred_date} – статус: {td.status}</li>
          ))}
        </ul>
      )}
    </motion.div>
  );
};

export default UserDashboard;
